/**
 * Assemble the vendored Selector editor into the two text assets the client
 * bundle ships, mirroring upstream `scripts/build.js`:
 *
 *   core → selection → ui → export → prompt → sharingan(strip header) → context
 *
 * Outputs:
 *  - `vendor/selector/editor.bundle.js` — the assembled editor payload.
 *  - `src/client/selector-assets.ts` — a GENERATED string module embedding the
 *    bundle and `editor.css` so they ship as text inside the client bundle
 *    (rolldown/tsdown has no `?raw` import, so this file is the fallback).
 *
 * The `editor.css` itself is the vendored upstream `assets/editor.css` and is
 * read (not regenerated) here.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const vendorDir = here
const pkgRoot = join(here, '..', '..')
const clientSrcDir = join(pkgRoot, 'src', 'client')

/** Fragment order — identical to upstream scripts/build.js. */
const editorPayloadParts = [
  { file: 'core.js', stripHeader: false },
  { file: 'selection.js', stripHeader: false },
  { file: 'ui.js', stripHeader: false },
  { file: 'export.js', stripHeader: false },
  { file: 'prompt.js', stripHeader: false },
  { file: 'sharingan.js', stripHeader: true },
  { file: 'context.js', stripHeader: false },
]

/** Drop the sharingan module's leading docblock, as upstream does. */
function stripSharinganHeader(source) {
  return source.replace(/^\s*\/\*\*[\s\S]*?\*\/\s*/, '')
}

const assembled = []
for (const part of editorPayloadParts) {
  let source = readFileSync(join(vendorDir, part.file), 'utf8')
  if (part.stripHeader) source = stripSharinganHeader(source)
  const output = source.trim() + '\n\n'
  if (output.includes('__SHARINGAN_MODULE__')) {
    throw new Error(`Unreplaced Sharingan marker in ${part.file}`)
  }
  assembled.push(output)
}
const editorBundle = assembled.join('')

// The assembled payload must remain valid JavaScript (mirrors upstream).
new Function(editorBundle)
writeFileSync(join(vendorDir, 'editor.bundle.js'), editorBundle)

const editorCss = readFileSync(join(vendorDir, 'editor.css'), 'utf8')

// JSON.stringify escapes backslashes, quotes and newlines, so the generated .ts
// is always valid regardless of the bundle/CSS content.
const assetsTs = [
  '// GENERATED by vendor/selector/build.mjs — do not edit by hand.',
  '// Rebuild via `npm run build` (build:client runs build.mjs first).',
  '',
  '/** Assembled Selector editor bundle (the injected page script). */',
  `export const editorBundle = ${JSON.stringify(editorBundle)}`,
  '',
  '/** Selector editor stylesheet (injected as a <style> element). */',
  `export const editorCss = ${JSON.stringify(editorCss)}`,
  '',
].join('\n')
writeFileSync(join(clientSrcDir, 'selector-assets.ts'), assetsTs)

console.log(`[selector] editor.bundle.js ${editorBundle.length} bytes, editor.css ${editorCss.length} bytes → src/client/selector-assets.ts`)
